   680→      }
   681→
   682→      chain.emitter.emit(routes.events.EventType.proposerSlashing, proposerSlashing);
   683→    },
   684→
   685→    [GossipType.voluntary_exit]: async ({gossipData, topic}: GossipHandlerParamGeneric<GossipType.voluntary_exit>) => {
   686→      const {serializedData} = gossipData;
   687→      const voluntaryExit = sszDeserialize(topic, serializedData);
   688→      await validateGossipVoluntaryExit(chain, voluntaryExit);
   689→
   690→      // Handler
   691→
   692→      try {
   693→        chain.opPool.insertVoluntaryExit(voluntaryExit);
   694→      } catch (e) {
   695→        logger.error("Error adding voluntaryExit to pool", {}, e as Error);
   696→      }
   697→
   698→      chain.emitter.emit(routes.events.EventType.voluntaryExit, voluntaryExit);
   699→    },
   700→
   701→    [GossipType.sync_committee_contribution_and_proof]: async ({
   702→      gossipData,
   703→      topic,
   704→    }: GossipHandlerParamGeneric<GossipType.sync_committee_contribution_and_proof>) => {
   705→      const {serializedData} = gossipData;
   706→      const contributionAndProof = sszDeserialize(topic, serializedData);
   707→      const {syncCommitteeParticipantIndices} = await validateSyncCommitteeGossipContributionAndProof(
   708→        chain,
   709→        contributionAndProof
   710→      ).catch((e) => {
   711→        if (e instanceof SyncCommitteeError && e.action === GossipAction.REJECT) {
   712→          chain.persistInvalidSszValue(ssz.altair.SignedContributionAndProof, contributionAndProof, "gossip_reject");
   713→        }
   714→        throw e;
   715→      });
   716→
   717→      // Handler
   718→      chain.validatorMonitor?.registerGossipSyncContributionAndProof(
   719→        contributionAndProof.message,
   720→        syncCommitteeParticipantIndices
   721→      );
   722→      try {
   723→        const insertOutcome = chain.syncContributionAndProofPool.add(
   724→          contributionAndProof.message,
   725→          syncCommitteeParticipantIndices.length
   726→        );
   727→        metrics?.opPool.syncContributionAndProofPool.gossipInsertOutcome.inc({insertOutcome});
   728→      } catch (e) {
   729→        logger.error("Error adding to contributionAndProof pool", {}, e as Error);
   730→      }
   731→
   732→      chain.emitter.emit(routes.events.EventType.contributionAndProof, contributionAndProof);
   733→    },
   734→
   735→    [GossipType.sync_committee]: async ({gossipData, topic}: GossipHandlerParamGeneric<GossipType.sync_committee>) => {
   736→      const {serializedData} = gossipData;
   737→      const syncCommittee = sszDeserialize(topic, serializedData);
   738→      const {subnet} = topic;
   739→      let indexInSubcommittee = 0;
   740→      try {
   741→        indexInSubcommittee = (await validateGossipSyncCommittee(chain, syncCommittee, subnet)).indexInSubcommittee;
   742→      } catch (e) {
   743→        if (e instanceof SyncCommitteeError && e.action === GossipAction.REJECT) {
